// Original Oxford maths and strategy laboratory. Source titles are tracked in docs/.
const LAB_ENGINES={},LAB_GAMES={};
function labRand(seed){let x=(Number(seed)||1)>>>0;return ()=>{x=(Math.imul(x,1664525)+1013904223)>>>0;return x/4294967296;};}
function labShuffle(items,r=Math.random){const a=[...items];for(let i=a.length-1;i>0;i--){const j=Math.floor(r()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
function labButton(a,label,n='',disabled=false,extra=''){return '<button type="button" class="button secondary" data-mode-action="lab-'+a+'" data-value="'+n+'" '+(disabled?'disabled ':'')+extra+'>'+label+'</button>';}
function labGrid(values,w,render=(v)=>esc(String(v)),action='cell'){return '<div class="lab-grid" style="--cols:'+w+'">'+values.map((v,i)=>labButton(action,render(v,i),i,false,'aria-label="Cell '+(i+1)+': '+esc(String(render(v,i)).replace(/<[^>]*>/g,''))+'"')).join('')+'</div>';}
function labOptions(a,values){return '<div class="lab-options">'+values.map((v,i)=>labButton(a,esc(String(v)),i)).join('')+'</div>';}
function labInit(){const c=LAB_GAMES[game.lesson.format],seed=Number(current().answer);game.session={engine:'activities',lab:true,phase:'play',groups:[],success:true,message:'',moves:0,config:c,seed,data:LAB_ENGINES[c.engine].init(c,seed)};}
function labRound(){const s=game.session;s.phase='play';s.message='';s.moves=0;s.seed=Number(current().answer);s.data=LAB_ENGINES[s.config.engine].init(s.config,s.seed);game.answered=false;game.feedbackGood=false;}
function labWin(message='Puzzle complete!'){const s=game.session;if(s.phase!=='play')return;s.phase='feedback';s.message=message;s.success=true;game.correct++;game.score+=100;game.attempts++;game.answered=true;game.feedbackGood=true;}
function labLose(message){const s=game.session;if(s.phase!=='play')return;s.phase='retry';s.message=message;s.success=false;game.attempts++;game.feedbackGood=false;}
function labMiss(message='Not quite. Adjust your move and try again.'){game.session.message=message;game.attempts++;game.feedbackGood=false;}
function labRender(){const s=game.session,c=s.config;$('#play-title').textContent=game.lesson.title;$('#play-format').textContent=c.name;$('#play-subtitle').textContent=GAME_MODES[c.mode].label;$('.player-bottom>span').textContent=c.mode==='DUEL'?'Two players · follow the turn or lane shown on the board.':'Explore the puzzle. Explain your strategy. Retry freely.';$('#scoreboard').innerHTML='<div class="class-score"><strong>'+game.score+' points · '+game.correct+'/'+game.items.length+' challenges</strong><span>'+s.moves+' moves</span></div>';let h='';
 if(game.done)h='<div class="result"><div class="result-icon">🏆</div><h2>All challenges complete!</h2><div class="result-actions"><button class="button primary" data-replay>Play again</button><button class="button secondary" data-edit-result>Edit lesson</button></div></div>';
 else if(s.phase!=='play')h='<div class="lab-celebrate">'+(s.phase==='feedback'?'🌟':'↻')+'</div><h2>'+esc(s.message)+'</h2>'+labButton(s.phase==='feedback'?'next':'retry',s.phase==='feedback'?'Next challenge →':'Try this challenge again');
 else h=(current().prompt===c.rule?'':'<h2>'+esc(current().prompt)+'</h2>')+LAB_ENGINES[c.engine].render(s.data,c)+'<p class="lab-status" role="status">'+esc(s.message)+'</p><div class="lab-tools">'+labButton('retry','Reset puzzle')+'</div>';
 $('#arena').innerHTML='<div class="lab-game" data-lab-engine="'+c.engine+'">'+h+'</div>';$('#arena').classList.add('activity-arena');requestAnimationFrame(()=>requestAnimationFrame(labFitBoard));LAB_ENGINES[c.engine].bind?.(s.data,c);
 $('#lab-form')?.addEventListener('submit',e=>{e.preventDefault();labHandle({dataset:{modeAction:'lab-submit'}});});
}
function labHandle(button){if(game.done||ui.view!=='player'||button.disabled)return;const s=game.session,a=button.dataset.modeAction.slice(4),n=Number(button.dataset.value);if(a==='retry'){labRound();renderGame();return;}if(s.phase==='feedback'&&a==='next'){game.index++;if(game.index===game.items.length){game.index--;game.done=true;}else labRound();renderGame();return;}if(s.phase!=='play')return;LAB_ENGINES[s.config.engine].action(s.data,a,n,s.config,button);renderGame();}
function labStep(dt){const s=game.session;if(s.phase==='play')LAB_ENGINES[s.config.engine].step?.(s.data,dt,s.config);}
function labValidate(raw,items){if(!LAB_GAMES[raw.format])return;if(items.some(q=>!/^([1-9]|[1-9][0-9])$/.test(q.answer)))throw Error('Choose a challenge number from 1 to 99 for each puzzle.');}
function labEditor(){if(!LAB_GAMES[draft?.format])return;document.querySelectorAll('[data-row]').forEach(row=>{const input=row.querySelector('[data-field="answer"]');input.parentElement.firstChild.textContent='Challenge number · 1–99 ';const note=document.createElement('p');note.textContent='The same number recreates the same puzzle. Generated puzzles vary by number; traditional board games retain their standard starting position. Edit the prompt to add lesson instructions.';row.append(note);});}

function labFitBoard(){if(innerWidth<1024||ui.view!=="player"||!game?.session?.lab)return;const arena=$("#arena");for(let pass=0;pass<3;pass++){const overflow=arena.scrollHeight-arena.clientHeight;if(overflow<3)break;const grids=[...arena.querySelectorAll(".lab-grid,.lab-mosaic")].sort((a,b)=>b.clientHeight-a.clientHeight);if(!grids.length)break;const grid=grids[0],size=grid.getBoundingClientRect(),width=Math.max(190,size.width*(size.height-overflow-8)/size.height);grid.style.maxWidth=width+"px";if(grid.matches("svg"))grid.style.height=Math.max(180,size.height-overflow-8)+"px";}}
